const dataset = $("Load Dataset").all();
const responses = $input.all();

const details = [];
let pass = 0;
let fail = 0;

for (let i = 0; i < dataset.length; i++) {
  const expected = dataset[i].json.expected;
  const input = dataset[i].json.input;
  const response = responses[i].json;

  // Template A: response is [[{label, score}, ...]] or [{label, score}, ...]
const results = Array.isArray(response[0]) ? response[0] : response;
const predicted = results[0].label;

  const status = (predicted.toLowerCase() === expected.toLowerCase()) ? "PASS" : "FAIL";
  if (status === "PASS") pass++; else fail++;

  details.push({input: input.substring(0, 60), expected, predicted, status});
}

const total = dataset.length;
const accuracy = ((pass / total) * 100).toFixed(1) + "%";

return [{json: {total, pass, fail, accuracy, details}}];
